  const learner = original.source_profiles?.find(source => source.kind === 'learning');
  const [selected, setSelected] = useState<Record<string, string>>({}), [relationship, setRelationship] = useState<'guardian' | 'mother' | 'father'>('guardian'), [primary, setPrimary] = useState(false), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const editor = usePeopleEditorGuard({ source: JSON.stringify([schoolId, person.id, 'guardian']), busy: writer.busy || busy, dirty: !!(Object.keys(selected).length || relationship !== 'guardian' || primary), onError: setError });
  async function save() { setBusy(true); setError(''); try { const context = captureApiContext(); const selectedId = Object.keys(selected)[0]; if (!selectedId) throw new Error('Choose a campus person.'); const other = await apiFetch<PersonDetail>(`${rootOf(schoolId)}/participants/${encodeURIComponent(selectedId)}`); context.assertCurrent(); if (other.id !== selectedId) throw new Error('The selected person could not be verified.'); const studentId = learner?.id ?? other.source_profiles?.find(source => source.kind === 'learning')?.id; if (!studentId) throw new Error('The selected person has no learner record. Complete enrollment before linking this contact.'); const guardian = learner ? other : original; if (await writer.run({ endpoint: '/api/v1/people/guardian-links', body: { school_id: schoolId, student_id: studentId, person: { id: guardian.id, expected_revision: guardian.revision }, relationship, is_primary: primary }, serverKey: 'idempotency_key', source: { kind: 'person', sourceId: guardian.id, revision: guardian.revision } })) editor.complete(onClose); } catch (cause) { setError(errorMessage(cause)); } finally { setBusy(false); } }
  return <Section title="Add family connection"><Notice message={learner ? `Choose a guardian for ${person.label}. Contact relationship, leave signing, collection authority and app access are separate.` : `Record ${person.label} as guardian of an enrolled learner. This adds no leave-signing, collection or app authority.`} /><PersonPicker schoolId={schoolId} selected={selected} onChange={setSelected} excludeId={person.id} disabled={writer.locked || busy} /><View style={{ gap: 8 }}>{(['guardian', 'mother', 'father'] as const).map(value => <Button key={value} title={value} kind={relationship === value ? 'primary' : 'secondary'} disabled={writer.locked || busy} onPress={() => setRelationship(value)} />)}</View><Button title={primary ? 'Primary contact: yes' : 'Primary contact: no'} kind="secondary" disabled={writer.locked || busy} onPress={() => setPrimary(!primary)} />{error ? <Notice tone="danger" message={error} /> : null}<Button title="Save family connection" busy={busy} disabled={writer.locked || !Object.keys(selected).length} onPress={() => void save()} /><Button title="Cancel" kind="secondary" disabled={writer.locked || busy} onPress={() => editor.leave(onClose)} /></Section>;
